const ROTENSO_EAN_CATALOG_BY_EAN = Object.freeze(Object.fromEntries(
  ROTENSO_EAN_CATALOG.map((entry) => [entry.ean, entry]),
));

export function getBuiltInRotensoCatalogEntry(ean = '') {
  const normalized = String(ean || '').replace(/\D/g, '');
  return ROTENSO_EAN_CATALOG_BY_EAN[normalized] || null;
}

export function isValidEan13(value = '') {
  const digits = String(value || '').replace(/\D/g, '');
  if (!/^\d{13}$/.test(digits)) return false;
  const sum = digits.slice(0, 12).split('').reduce((total, digit, index) => total + Number(digit) * (index % 2 === 0 ? 1 : 3), 0);
  return (10 - (sum % 10)) % 10 === Number(digits[12]);
}
